/* Original beginner lessons; examples and tasks deliberately use different values. */
const pythonLessons=[];
function pythonLesson(id,stage,title,goal,why,explain,example,lines,task,starter,solution,checks,output,question,correct,wrong,feedback,syntax=[]){pythonLessons.push({id,stage,title,goal,why,explain,example,lines,task,starter,solution,checks,output,quiz:choiceTask(question,correct,wrong,feedback,pythonLessons.length),syntax});}
pythonLesson('hello',0,'第一行代码：把结果显示出来','用 print 输出一句话。','巡检脚本首先要把检查结果告诉人。print 就像在终端写一句话。','代码从上到下执行。print(...) 把括号里的内容显示出来；文字要放在成对的英文引号中。# 后面的内容是注释，不会执行。',`# 显示一条消息\nprint("开始检查")`,['第 1 行是给人看的注释。','第 2 行把“开始检查”输出到结果区；英文括号和引号必须成对。'],'输出“开始巡检”，不要输出引号。',`# 在下一行写 print\n`, `print("开始巡检")`,[],'开始巡检','print 的作用是什么？','把内容显示到输出区',['把文本保存成数据库表','自动检查服务器健康'],'输出是程序展示结果的方式，不能凭一句“正常”证明服务器真的健康。');
pythonLesson('variables',0,'变量：给一个值取名字','保存服务名并输出。','把服务名放进变量，后面改一处就能复用。','变量名 = 值 表示赋值，不是数学等式。文字用字符串表示。命名使用清楚的英文词和下划线，不能用数字开头。',`service = "nginx"\nprint(service)`,['第一行把字符串 nginx 交给变量 service。','第二行读取 service 的值；print("service") 则会输出字面文本 service。'],'创建 service 变量，值为 order-api，然后输出它。',`service = ""\nprint(service)`, `service = "order-api"\nprint(service)`,["service == 'order-api'"],'order-api','print(service) 与 print("service") 有什么区别？','前者读取变量，后者输出字面文本',['两者永远相同','前者会连接服务'],'引号决定你写的是文字，还是变量名。');
pythonLesson('numbers',0,'数字与计算：统计总数','计算成功和失败请求的总数。','错误率、磁盘使用比例都建立在数字运算上。','整数可以直接计算，+ 是加法，/ 是除法。先确认数据含义再计算；分母为 0 时不能直接相除。',`ok = 8\nfailed = 2\ntotal = ok + failed\nprint(total)`,['先保存成功和失败的数量。','total 保存相加后的结果，print 再展示结果。'],'ok=90、failed=10，创建 total 并输出总请求数。',`ok = 90\nfailed = 10\n# 创建 total，再输出\n`, `ok = 90\nfailed = 10\ntotal = ok + failed\nprint(total)`,['ok == 90','failed == 10','total == 100'],'100','为什么计算错误率前要检查总请求数？','避免把 0 当作除法的分母',['Python 不支持小数','成功请求不能计数'],'总数为 0 时需要单独处理。');
pythonLesson('convert',0,'类型转换：日志里的“500”是文字','把状态码字符串转成整数。','日志读出来通常是文字；比较数值前先转换类型。','"500" 是字符串，500 是整数。int(text) 尝试把文本转成整数，无法转换时会报 ValueError。str(number) 则转成文字。',`text = "200"\nstatus = int(text)\nprint(status + 1)`,['int 把数字文字转成整数。','转换后才能按数值做加法；不会变成字符串拼接。'],'把 raw_status="500" 转成整数 status，再输出 status+1。',`raw_status = "500"\n# 转换后再计算\n`, `raw_status = "500"\nstatus = int(raw_status)\nprint(status + 1)`,['type(status) is int','status == 500'],'501','int("abc") 会怎样？','报出无法转换的错误',['得到 0','得到字符串 abc'],'转换不是猜测；后面的异常课会处理这种错误。');
pythonLesson('if',1,'条件判断：区分成功和错误','根据状态码决定输出。','同一条巡检脚本需要针对不同结果采取不同分支。','if 条件: 后的缩进代码只在条件成立时执行。else: 处理其他情况。== 比较相等，>= 比较大小；缩进建议统一用四个空格。',`status = 200\nif status >= 500:\n    print("服务错误")\nelse:\n    print("未出现服务端错误")`,['if 行末尾有冒号。','缩进说明哪些代码属于这个分支；else 与 if 对齐。'],'status=503；用 if 判断是否 >=500，输出“告警”，否则输出“观察”。',`status = 503\n# 在下面写 if / else\n`, `status = 503\nif status >= 500:\n    print("告警")\nelse:\n    print("观察")`,['status == 503'],'告警','Python 用什么标识分支内的代码？','缩进',['只靠空白行','HTML 标签'],'冒号引出代码块，缩进说明代码的归属。',['If']);
pythonLesson('list',1,'列表：保存多台服务的结果','建立状态码列表并读其中一项。','一组检测结果可以放进列表，不必为每个结果起一个变量。','列表用 []，元素用逗号分隔。下标从 0 开始：items[0] 是第一个元素。len(items) 返回元素数量。',`codes = [200, 404, 503]\nprint(codes[0])\nprint(len(codes))`,['codes[0] 读第一个状态码 200。','len 返回 3，不是最后一个下标 2。'],'创建 codes=[200,500,502]，先输出第二项，再输出数量。',`codes = []\n# 输出第二项与数量，各占一行\n`, `codes = [200, 500, 502]\nprint(codes[1])\nprint(len(codes))`,['codes == [200,500,502]'],'500\n3','三项列表的第二项下标是多少？','1',['2','3'],'从 0 计数，所以第二项的下标是 1。');
pythonLesson('loop',1,'for 循环：数一数错误请求','逐个检查列表，统计 >=500 的数量。','循环把重复检查交给程序；先确定规则，再写循环。','for item in items: 每次取出一个元素。累计变量要在循环前设为 0；count += 1 相当于 count = count + 1。',`codes = [200, 503, 200]\ncount = 0\nfor code in codes:\n    if code >= 500:\n        count += 1\nprint(count)`,['count 在循环外初始化，避免每次重新归零。','print 放在循环后，输出最终总数。'],'codes=[200,500,502,404]；使用 for 和 if 统计错误数，保存在 count 并输出。',`codes = [200, 500, 502, 404]\ncount = 0\n# 写循环\n`, `codes = [200, 500, 502, 404]\ncount = 0\nfor code in codes:\n    if code >= 500:\n        count += 1\nprint(count)`,['count == 2','codes == [200,500,502,404]'],'2','count=0 应放在哪里？','开始循环之前',['每次循环里面','输出结果之后'],'累计值放在循环外初始化。',['For']);
pythonLesson('dict',1,'字典：给结果加上字段名','用字典组织一份服务状态。','字典像一张小记录：服务名、状态码各有自己的字段。','字典用 {}，键与值用冒号连接，项目用逗号隔开。record["status"] 按键取值，键名不对会报 KeyError。',`record = {"service": "nginx", "status": 200}\nprint(record["service"])`,['service 与 status 是两个键。','按键读取比按位置猜测数据含义更明确。'],'创建 record，service 为 order-api，status 为 503，然后输出状态码。',`record = {}\n# 按键读取 status\n`, `record = {"service": "order-api", "status": 503}\nprint(record["status"])`,["record == {'service':'order-api','status':503}"],'503','字典按什么读取对应的值？','键',['列表长度','文件大小'],'键名应该与数据约定一致。');
pythonLesson('function',2,'函数：让判断可以复用','定义 health_label(status)，返回状态标签。','把规则写成函数后，可以为多个服务复用并单独测试。','def 名称(参数): 定义函数。return 把结果交回调用方；print 只是显示，不能替代 return。函数体需要缩进。',`def is_error(status):\n    return status >= 500\nprint(is_error(503))`,['status 是调用时传入的参数。','return 返回布尔值，调用方可以继续判断。'],'定义 health_label(status)：>=500 返回“告警”，其他值返回“正常”；输出 health_label(503)。',`def health_label(status):\n    # 返回标签\n    pass\n\nprint(health_label(503))`, `def health_label(status):\n    if status >= 500:\n        return "告警"\n    return "正常"\n\nprint(health_label(503))`,["health_label(200) == '正常'","health_label(499) == '正常'","health_label(500) == '告警'","health_label(503) == '告警'"],'告警','return 与 print 的主要区别是什么？','return 交回结果，print 显示内容',['完全没有区别','return 自动打印'],'函数需要把结果交给调用者。',['FunctionDef']);
pythonLesson('strings',2,'字符串：把一行日志拆成字段','用 split 从日志中取出状态码。','在做日志统计前，先认识格式、分隔符和字段位置。','text.strip() 去掉首尾空白；text.split() 按空白拆分。先观察格式，再按下标取字段；不同格式不能直接套用。',`line = "GET /health 200"\nparts = line.split()\nprint(parts[2])`,['本例第三个字段是状态码。','取出的仍是文字；需要 int 才变成数值。'],'line="GET /api/orders 500"；拆成 parts，把第三项转成整数 status 并输出。',`line = "GET /api/orders 500"\n# 拆分、转换、输出\n`, `line = "GET /api/orders 500"\nparts = line.split()\nstatus = int(parts[2])\nprint(status)`,["parts == ['GET','/api/orders','500']",'type(status) is int','status == 500'],'500','按列解析日志前首先要确认什么？','日志格式与字段位置',['先删除空行以外的记录','永远用第三列'],'先看格式，避免把路径等字段误当状态码。');
pythonLesson('filter',2,'筛选列表：留下需要调查的记录','用循环和 append 收集错误状态码。','计数回答“多少”，筛选回答“具体哪些”。','创建空列表后，append(value) 把一个元素加到末尾。筛选不会自动修改原列表。也可以用列表推导式，但先把循环读懂。',`codes = [200, 503, 404]\nerrors = []\nfor code in codes:\n    if code >= 500:\n        errors.append(code)\nprint(errors)`,['errors 开始是空列表。','只有匹配条件的元素会被 append 加入。'],'codes=[200,500,502,404]；把 >=500 的元素收集到 errors，再输出列表。',`codes = [200, 500, 502, 404]\nerrors = []\n# 筛选后输出\n`, `codes = [200, 500, 502, 404]\nerrors = []\nfor code in codes:\n    if code >= 500:\n        errors.append(code)\nprint(errors)`,['errors == [500,502]','codes == [200,500,502,404]'],'[500, 502]','append 会怎样？','在列表末尾添加一个元素',['自动排序所有元素','清空原列表'],'筛选与排序是不同操作。',['For','ListComp']);
pythonLesson('json',2,'JSON：读懂接口返回的数据','把 JSON 文本转换成字典。','接口响应常用 JSON；解析后才能按字段处理。','import json 引入标准库。json.loads(text) 从文本解析数据，json.dumps(data) 把对象转回 JSON 文本。JSON 中字符串用双引号。',`import json\ntext = '{"service":"nginx","status":200}'\nrecord = json.loads(text)\nprint(record["service"])`,['text 是字符串，record 是解析后的字典。','按键 service 读取字段，不靠字符串位置猜测。'],'解析 payload 为 record，然后输出 status 字段。',`import json\npayload = '{"service":"order-api","status":503}'\n# 解析并输出\n`, `import json\npayload = '{"service":"order-api","status":503}'\nrecord = json.loads(payload)\nprint(record["status"])`,["record == {'service':'order-api','status':503}"],'503','json.loads 接收什么？','JSON 文本',['服务器密码','SQL 表名'],'loads 解析字符串；load 用于可读取的文件对象。',['Import']);
pythonLesson('read-file',3,'读文件：逐行统计教学日志','打开 app.log，统计 ERROR 行数。','日志文件可能很大，逐行读取更容易限定处理范围。','with open(path, encoding="utf-8") as f: 打开文件，并在离开代码块时关闭。for line in f: 逐行读取。这里的文件是网页内提供的教学样本。',`with open("app.log", encoding="utf-8") as f:\n    for line in f:\n        print(line.strip())`,['with 管理文件打开与关闭。','strip 去掉每行结尾的换行，让输出更整齐。'],'教学 app.log 有 4 行，其中 2 行以 ERROR 开头；逐行统计到 count 并输出。',`count = 0\nwith open("app.log", encoding="utf-8") as f:\n    # 遍历并统计 ERROR 行\n    pass\n`, `count = 0\nwith open("app.log", encoding="utf-8") as f:\n    for line in f:\n        if line.startswith("ERROR"):\n            count += 1\nprint(count)`,['count == 2'],'2','with open 的好处是什么？','离开代码块时自动关闭文件',['自动修复日志中的错误','直接打开公司服务器文件'],'文件在本课堂的临时运行环境里，不是本机或公司文件。',['With']);
pythonLesson('exceptions',3,'异常处理：坏数据不能悄悄变成成功','为端口转换处理 ValueError。','接口或配置出现坏数据时，要给明确结果，而不是让整个脚本中断。','try 中放可能失败的操作，except ValueError: 处理特定转换错误。不要用一个宽泛异常把所有错误都说成“正常”。',`try:\n    port = int("8080")\n    print(port)\nexcept ValueError:\n    print("端口不是数字")`,['有效输入走 try；无法转换才进入 except。','只捕获预期错误，其他问题继续暴露。'],'定义 parse_port(text)，可转成整数时返回整数，遇到 ValueError 返回 None；输出 parse_port("abc")。',`def parse_port(text):\n    # 使用 try / except ValueError\n    pass\n\nprint(parse_port("abc"))`, `def parse_port(text):\n    try:\n        return int(text)\n    except ValueError:\n        return None\n\nprint(parse_port("abc"))`,["parse_port('8080') == 8080","parse_port('5236') == 5236","parse_port('abc') is None"],'None','为什么不把坏输入直接当成正常端口？','会隐藏故障，结果失去可信度',['因为 Python 不能返回数字','异常总是可以忽略'],'None 明确表示这里没有得到可用结果；端口范围检查是下一层业务校验。',['Try']);
pythonLesson('write-report',3,'写报告：把证据保存下来','把统计结果写入教学 report.txt，再读回。','报告是交接材料；写入成功后还应检查内容。','open(...,"w") 覆盖写文件；write 写入文字；再用读模式核对。此课堂每次运行会重置教学文件，保存进度不会保存运行文件。',`with open("report.txt", "w", encoding="utf-8") as f:\n    f.write("errors=1")\nwith open("report.txt", encoding="utf-8") as f:\n    print(f.read())`,['w 会覆盖目标文件，不是追加。','读回验证记录内容，不只看没有报错。'],'写入 report.txt，内容为 errors=2；再读文件保存到 content 并输出。',`# 写文件，再读回到 content\n`, `with open("report.txt", "w", encoding="utf-8") as f:\n    f.write("errors=2")\nwith open("report.txt", encoding="utf-8") as f:\n    content = f.read()\nprint(content)`,["content == 'errors=2'","open('report.txt',encoding='utf-8').read() == 'errors=2'"],'errors=2','文件模式 w 的含义是什么？','覆盖写入',['只读','永远追加'],'练习文件可重建，真实环境要先确认路径与覆盖影响。',['With']);
pythonLesson('mini-project',3,'综合练习：生成一份巡检摘要','读取 JSON 样本，计算失败服务数量并输出报告。','把解析、循环、判断和输出连接成一个小程序。','本课 health.json 提供三条教学状态：200、503、502。report 包含 total 和 failed。它只能总结样本，不能证明真实服务可用。',`import json\nrecords = [{"status":200},{"status":503}]\nfailed = 0\nfor record in records:\n    if record["status"] >= 500:\n        failed += 1\nprint(json.dumps({"total":len(records),"failed":failed}, sort_keys=True))`,['每一项是字典，列表承载多条结果。','最后一次性序列化报告，sort_keys 固定字段顺序便于阅读。'],'读取 health.json 到 records，统计 failed，构建 report={"total":3,"failed":2}，用 json.dumps(report, sort_keys=True) 输出。',`import json\nwith open("health.json", encoding="utf-8") as f:\n    records = json.load(f)\n# 统计、构建 report、输出\n`, `import json\nwith open("health.json", encoding="utf-8") as f:\n    records = json.load(f)\nfailed = 0\nfor record in records:\n    if record["status"] >= 500:\n        failed += 1\nreport = {"total": len(records), "failed": failed}\nprint(json.dumps(report, sort_keys=True))`,["report == {'total':3,'failed':2}",'failed == 2','len(records) == 3'],'{"failed": 2, "total": 3}','这份报告能证明什么？','教学样本中有三条记录，其中两条状态码 >=500',['所有公司服务器都健康','数据库备份已经恢复成功'],'报告的结论必须限定在实际采集的证据范围内。',['For']);
const pythonStages=['认识代码与数据','判断与批量处理','复用规则与解析数据','日志、异常与巡检报告'];
